// Add event listeners to boats for dragging and rotating
export function addBoatEventListeners() {
    const { infoBox } = getDOMElements();
    const boats = Array.from(document.getElementsByClassName("boat"));
    boats.forEach((boat) => {
        // allow dragging from whole boat
        boat.draggable = true;
        boat.addEventListener("dragstart", (e) => {
            if (!e.dataTransfer)
                return;
            if (infoBox)
                infoBox.textContent =
                    "Place your ships on the grid. Click to rotate ship";
            // figure out which child index was clicked
            let clickedIndex = 0;
            const targetEl = e.target;
            if (targetEl && targetEl.classList.contains("boatSquare")) {
                clickedIndex = Array.from(boat.children).indexOf(targetEl);
            }
            else {
                // fallback: approximate by position within element
                const rect = boat.getBoundingClientRect();
                const isVertical = boat.classList.contains("vertical");
                const offset = isVertical
                    ? e.clientY - rect.top
                    : e.clientX - rect.left;
                const size = isVertical
                    ? rect.height / boat.children.length
                    : rect.width / boat.children.length;
                clickedIndex = Math.floor(offset / size);
                if (clickedIndex < 0)
                    clickedIndex = 0;
                if (clickedIndex >= boat.children.length)
                    clickedIndex = boat.children.length - 1;
            }
            // populate module-level state
            dragState.boatID = boat.id;
            dragState.boatClass = Array.from(boat.classList).toString();
            dragState.clickedIndex = clickedIndex;
            dragState.dragging = true;
            // also set for drop handler compatibility
            e.dataTransfer.setData("text", boat.id);
            e.dataTransfer.setData("text/class", dragState.boatClass);
            e.dataTransfer.setData("text/offset", String(clickedIndex));
            // compute drag image offset so it follows cursor
            const rect = boat.getBoundingClientRect();
            const offsetX = e.clientX - rect.left;
            const offsetY = e.clientY - rect.top;
            e.dataTransfer.setDragImage(boat, offsetX, offsetY);
        });
        boat.addEventListener("dragend", () => {
            dragState.boatID = null;
            dragState.boatClass = "";
            dragState.clickedIndex = 0;
            dragState.dragging = false;
            clearPreview();
        });
        // toggle vertical orientation on click
        boat.addEventListener("click", () => {
            boat.classList.toggle("vertical");
        });
    });
    if (infoBox) {
        infoBox.textContent = "Place your ships on the grid. Click to rotate ship";
    }
}
